/* ── موقع الملف من رابط المكان نفسه — في الذاكرة فقط ولا يُكتب (٠٩-١٥-٠٥) ── */
function tkFileLocOf(p){ const url = String((p && (p.url2 || p.url)) || ''); if (!url) return null; /* r86 (البند ٨): القديم المترقّي يحمل رابطه الطويل في url2 — يُقرأ كما يُقرأ رابط المستورَد · في الذاكرة فقط */ const ids = tkIdsFromUrl(url); if (ids.cell){ const c = tkCellToLatLng(ids.cell); if (c) return { lat: c.lat, lng: c.lng }; } const m = /maps\/search\/(-?\d+\.\d+),(-?\d+\.\d+)/.exec(url) || /[?&]q=(-?\d+\.\d+),(-?\d+\.\d+)/.exec(url); return m ? { lat: +m[1], lng: +m[2] } : null; }
function tkNameExact(a, b){ const x = pickerNormalize(String(a || '')), y = pickerNormalize(String(b || '')); return !!x && x === y; }
function tkNameContains(a, b){ const A = tkWords(a), B = tkWords(b); if (!A || !B || A === B) return false; const sh = A.length <= B.length ? A : B, lo = A.length <= B.length ? B : A; if (sh.replace(/\s/g, '').length < 4) return false; return (' ' + lo + ' ').indexOf(' ' + sh + ' ') >= 0; } /* r86-3: «Dishoom Covent Garden» ↔ «Dishoom» — كلمات كاملة · القصير ≥ ٤ أحرف */
function tkPostcodeOf(s){ const t = String(s || '').toUpperCase(); const uk = t.match(/\b([A-Z]{1,2}\d[A-Z\d]?)\s*(\d[A-Z]{2})\b/); if (uk) return uk[1] + ' ' + uk[2]; const num = t.match(/\b(\d{5})\b/); return num ? num[1] : ''; } /* r86-3: الرمز البريدي من العنوان — بريطاني (WC2H 9JS) أو خمسة أرقام */
