    + '<button type="button" class="cta" style="display:block; width:100%; margin-top:10px;"' + (n ? '' : ' disabled') + ' onclick="tkConfirmGo()">Confirm ' + n + ' pin' + (n === 1 ? '' : 's') + '</button><button type="button" class="btn btn-ghost" style="margin-top:8px; padding:7px 14px; font-size:12px;" onclick="closeModalById(\'dashBackdrop\')">Not now</button>'
